// FUNCTION: BFME2 0x0045679B size=194 name=?parseTimeAndLocationInfo@@YAXPAVINI@@PAXPAUTimeAndLocationInfo@@@Z evidence=N:ledger
// Parses "Delay:#### <Bone:BoneName>".
static void parseTimeAndLocationInfo(INI *ini, void *instance, TimeAndLocationInfo *timeAndLocationInfo)
{
	const char *token = ini->getNextToken(ini->getSepsColon());
	if (BridgeBehaviorCRT::_strcmpi(token, "Delay") != 0)
		throw INIException(3, "Expected 'Delay' token, found '%s'\n", token);

	ini->parseDurationUnsignedInt(ini, instance, &timeAndLocationInfo->delay, NULL);

	token = ini->getNextTokenOrNull(ini->getSepsColon());
	if (token)
	{
		if (BridgeBehaviorCRT::_strcmpi(token, "Bone") != 0)
			throw INIException(3, "Expected 'Bone' token, found '%s'\n", token);
		timeAndLocationInfo->boneName = ini->getNextAsciiString();
	}
}

// FUNCTION: BFME2 0x0045685D size=143 name=?doAreaEffects@BridgeBehavior@@IAEXPAVTerrainRoadType@@PAVBridge@@PBVObjectCreationList@@PBVFXList@@@Z evidence=N:ledger
void BridgeBehavior::doAreaEffects(TerrainRoadType *bridgeTemplate, Bridge *bridge, const ObjectCreationList *ocl, const FXList *fx)
{
	if (bridge == 0)
		return;

	if (ocl == 0 && fx == 0)
		return;

	const BridgeInfo *bridgeInfo = bridge->peekBridgeInfo();

	Int maxEffects = bridgeTemplate->getNumFXPerType();

	Coord3D pos;
	for (Int i = 0; i < maxEffects; ++i)
	{
		if (fx)
		{
			getRandomSurfacePosition(bridgeTemplate, bridgeInfo, &pos);
			FXList::doFXPos(fx, &pos, 0, 0.0f, 0);
		}

		if (ocl)
		{
			getRandomSurfacePosition(bridgeTemplate, bridgeInfo, &pos);
			const_cast<ObjectCreationList *>(ocl)->create(getObject(), &pos, 0, 0);
		}
	}
}

// FUNCTION: BFME2 0x004568EC size=338 name=?setScaffoldData@BridgeBehavior@@IAEXPAVObject@@PAM1PBUCoord3D@@22@Z evidence=N:ledger
void BridgeBehavior::setScaffoldData(Object *object, float *angle, float *sunkenHeight,
    const Coord3D *risePosition, const Coord3D *buildPosition, const Coord3D *bridgeCenter)
{
    if (!object) return;
    if (!angle) return;
    if (!risePosition) return;
    if (!buildPosition) return;
    const BridgeBehaviorModuleData *data = static_cast<const BridgeBehaviorModuleData *>(getModuleData());
    BridgeScaffoldBehaviorInterface *scaffold =
        BridgeScaffoldBehavior::getBridgeScaffoldBehaviorInterfaceFromObject(object);
    Coord3D sunkenPosition;
    sunkenPosition.x = risePosition->x;
    sunkenPosition.y = risePosition->y;
    sunkenPosition.z = risePosition->z - *sunkenHeight - 8.0f;
    object->setPosition(&sunkenPosition);
    scaffold->setPositions(&sunkenPosition, risePosition, buildPosition);
    scaffold->setMotion(STM_RISE);
    object->setOrientation(*angle);
    float lateralSpeed = data->m_lateralScaffoldSpeed;
    Coord3D buildToCenter;
    buildToCenter.x = buildPosition->x - risePosition->x;
    buildToCenter.y = buildPosition->y - risePosition->y;
    buildToCenter.z = buildPosition->z - risePosition->z;
    Coord3D riseToCenter;
    riseToCenter.x = bridgeCenter->x - risePosition->x;
    riseToCenter.y = bridgeCenter->y - risePosition->y;
    riseToCenter.z = bridgeCenter->z - risePosition->z;
    float buildDistance = buildToCenter.length();
    float riseDistance = riseToCenter.length();
    scaffold->setLateralSpeed(lateralSpeed * (buildDistance / riseDistance));
    float verticalSpeed = data->m_verticalScaffoldSpeed;
    scaffold->setVerticalSpeed(verticalSpeed);
}

// FUNCTION: BFME2 0x00456A49 size=470 name=?resolveFX@BridgeBehavior@@IAEXXZ evidence=N:ledger
void BridgeBehavior::resolveFX()
{
	Object *us = getObject();
	Bridge *bridge = TheTerrainLogic->findBridgeAt(us->getPosition());

	if (bridge == 0)
		return;

	// the bridge's template
	AsciiString bridgeTemplateName = bridge->getBridgeTemplateName();
	TerrainRoadType *bridgeTemplate = TheTerrainRoads->findBridge(bridgeTemplateName);

	if (bridgeTemplate == 0)
		return;

	AsciiString name;
	for (Int bodyState = BODY_PRISTINE; bodyState < BODYDAMAGETYPE_COUNT; ++bodyState)
	{
		for (Int i = 0; i < 3; ++i)
		{
			name = bridgeTemplate->getDamageToOCLString((BodyDamageType)bodyState, i);
			m_damageToOCL[bodyState][i] = TheObjectCreationListStore->findObjectCreationList(name.str());

			name = bridgeTemplate->getDamageToFXString((BodyDamageType)bodyState, i);
			m_damageToFX[bodyState][i] = TheFXListStore->findFXList(name.str());

			name = bridgeTemplate->getRepairedToOCLString((BodyDamageType)bodyState, i);
			m_repairToOCL[bodyState][i] = TheObjectCreationListStore->findObjectCreationList(name.str());

			name = bridgeTemplate->getRepairedToFXString((BodyDamageType)bodyState, i);
			m_repairToFX[bodyState][i] = TheFXListStore->findFXList(name.str());
		}
	}

	m_fxResolved = true;
}

// FUNCTION: BFME2 0x00456C1F size=593 name=?onBodyDamageStateChange@BridgeBehavior@@UAEXPBVDamageInfo@@W4BodyDamageType@@1@Z evidence=N:ledger
void BridgeBehavior::onBodyDamageStateChange(const DamageInfo *damageInfo, BodyDamageType oldState, BodyDamageType newState)
{
	// coming back from the dead: a state that is not rubble cannot be dead
	if (newState != BODY_RUBBLE)
		m_deathFrame = 0;

	if (m_fxResolved == false)
		resolveFX();

	if (m_fxResolved == false)
		return;

	Object *us = getObject();
	Bridge *bridge = TheTerrainLogic->findBridgeAt(us->getPosition());

	if (bridge == 0)
		return;

	AsciiString bridgeTemplateName = bridge->getBridgeTemplateName();
	TerrainRoadType *bridgeTemplate = TheTerrainRoads->findBridge(bridgeTemplateName);

	// did we get worse (damaged) or better (repaired)?
	Bool gotRepaired = oldState > newState;

	AsciiString soundString;
	AsciiString oclString[3];
	AsciiString fxString[3];
	if (gotRepaired)
	{
		if (bridgeTemplate)
		{
			AudioEventRTS sound(reinterpret_cast<const OpaqueRefElement4 &>(bridgeTemplate->getRepairedToSoundString(newState)), 0);
			sound.setObjectID(us->getID());
			TheAudio->addAudioEvent(&sound);
		}

		for (Int i = 0; i < 3; i++)
			doAreaEffects(bridgeTemplate, bridge, m_repairToOCL[newState][i], m_repairToFX[newState][i]);
	}
	else
	{
		if (bridgeTemplate)
		{
			AudioEventRTS sound(reinterpret_cast<const OpaqueRefElement4 &>(bridgeTemplate->getDamageToSoundString(newState)), 0);
			sound.setObjectID(us->getID());
			TheAudio->addAudioEvent(&sound);
		}

		for (Int i = 0; i < 3; i++)
			doAreaEffects(bridgeTemplate, bridge, m_damageToOCL[newState][i], m_damageToFX[newState][i]);
	}

	TheTerrainLogic->updateBridgeDamageStates();

	// the local player's radar reflects a switch from or to rubble
	if (oldState == BODY_RUBBLE || newState == BODY_RUBBLE)
		TheRadar->queueTerrainRefresh();
}

// FUNCTION: BFME2 0x00456E8D size=592 name=?update@BridgeBehavior@@UAE?AW4UpdateSleepTime@@XZ evidence=N:ledger
UpdateSleepTime BridgeBehavior::update()
{
	// if we're dead, we need to possibly throw off some effects
	if (m_deathFrame != 0)
	{
		AsciiString boneName;

		Object *us = getObject();

		const BridgeBehaviorModuleData *modData = (const BridgeBehaviorModuleData *)getModuleData();

		// the bridge and its template
		Bridge *bridge = TheTerrainLogic->findBridgeAt(us->getPosition());
		const BridgeInfo *bridgeInfo = 0;
		TerrainRoadType *bridgeTemplate = 0;
		if (bridge)
		{
			bridgeInfo = bridge->peekBridgeInfo();

			AsciiString bridgeTemplateName = bridge->getBridgeTemplateName();
			bridgeTemplate = TheTerrainRoads->findBridge(bridgeTemplateName);
		}

		// how much time has passed since our destruction frame
		UnsignedInt deathTime = TheGameLogic->getFrame() - m_deathFrame;

		// fx visuals to execute: a list launches when the death time is exactly its delay
		for (BridgeFXList::const_iterator fxIt = modData->m_bridgeDieFX.begin(); fxIt != modData->m_bridgeDieFX.end(); ++fxIt)
		{
			if (deathTime == fxIt->timeAndLocationInfo.delay)
			{
				Coord3D pos;

				// a bone name gives the bone position, otherwise a spot on the bridge surface
				boneName = fxIt->timeAndLocationInfo.boneName;
				if (boneName.isEmpty() == false)
					us->getSingleLogicalBonePosition(boneName.str(), &pos, 0);
				else if (bridge && bridgeTemplate && bridgeInfo)
					getRandomSurfacePosition(bridgeTemplate, bridgeInfo, &pos);
				else
				{
					pos.x = getObject()->getPosition()->x;
					pos.y = getObject()->getPosition()->y;
					pos.z = getObject()->getPosition()->z;
				}

				FXList::doFXPos(fxIt->fx, &pos, 0, 0.0f, 0);
			}
		}

		// ocl visuals to execute
		for (BridgeOCLList::const_iterator oclIt = modData->m_bridgeDieOCL.begin(); oclIt != modData->m_bridgeDieOCL.end(); ++oclIt)
		{
			if (deathTime == oclIt->timeAndLocationInfo.delay)
			{
				Coord3D pos;

				boneName = oclIt->timeAndLocationInfo.boneName;
				if (boneName.isEmpty() == false)
				{
					// creating an OCL at the bridge object's own center
					if (boneName.compare("ParentObject") == 0)
					{
						if (oclIt->ocl)
							const_cast<ObjectCreationList *>(oclIt->ocl)->create(us, 0, 0);
						continue;
					}

					us->getSingleLogicalBonePosition(boneName.str(), &pos, 0);
				}
				else if (bridge && bridgeTemplate && bridgeInfo)
					getRandomSurfacePosition(bridgeTemplate, bridgeInfo, &pos);
				else
				{
					pos.x = getObject()->getPosition()->x;
					pos.y = getObject()->getPosition()->y;
					pos.z = getObject()->getPosition()->z;
				}

				if (oclIt->ocl)
					const_cast<ObjectCreationList *>(oclIt->ocl)->create(us, &pos, 0, 0);
			}
		}
	}

	return UPDATE_SLEEP_NONE;
}

