// FUNCTION: BFME2 0x004571FB size=182 name=?onDamage@BridgeBehavior@@UAEXPAVDamageInfo@@@Z evidence=N:ledger
void BridgeBehavior::onDamage(DamageInfo *damageInfo)
{
	BodyModuleInterface *body = getObject()->getBodyModule();
	Real damagePercentage = damageInfo->in.m_amount / body->getMaxHealth();

	Object *source = TheGameLogic->findObjectByID(damageInfo->in.m_sourceID);
	if (source == 0 || !source->getTemplate()->isKindOf(KINDOF_BRIDGE_TOWER))
	{
		for (Int i = 0; i < BRIDGE_MAX_TOWERS; i++)
		{
			Object *tower = TheGameLogic->findObjectByID(getTowerID((BridgeTowerType)i));
			if (tower)
			{
				BodyModuleInterface *towerBody = tower->getBodyModule();
				DamageInfo towerDamage;
				towerDamage.in.m_amount = damagePercentage * towerBody->getMaxHealth();
				towerDamage.in.m_sourceID = getObject()->getID();
				towerDamage.in.m_damageType = damageInfo->in.m_damageType;
				towerDamage.in.m_deathType = damageInfo->in.m_deathType;
				tower->attemptDamage(&towerDamage);
			}
		}
	}
}

// FUNCTION: BFME2 0x004572B1 size=141 name=?onHealing@BridgeBehavior@@UAEXPAVDamageInfo@@@Z evidence=N:ledger
void BridgeBehavior::onHealing(DamageInfo *damageInfo)
{
	BodyModuleInterface *body = getObject()->getBodyModule();
	Real healingPercentage = damageInfo->in.m_amount / body->getMaxHealth();

	Object *source = TheGameLogic->findObjectByID(damageInfo->in.m_sourceID);
	if (source == 0 || !source->getTemplate()->isKindOf(KINDOF_BRIDGE_TOWER))
	{
		for (Int i = 0; i < BRIDGE_MAX_TOWERS; i++)
		{
			Object *tower = TheGameLogic->findObjectByID(getTowerID((BridgeTowerType)i));
			if (tower)
			{
				BodyModuleInterface *towerBody = tower->getBodyModule();
				tower->attemptHealing(healingPercentage * towerBody->getMaxHealth(), getObject());
			}
		}
	}
}

// FUNCTION: BFME2 0x0045733E size=150 name=?removeScaffolding@BridgeBehavior@@UAEXXZ evidence=N:ledger
void BridgeBehavior::removeScaffolding()
{
    if (!m_scaffoldPresent)
        return;
    ObjectIDListIterator it = m_scaffoldObjectIDList.begin();
    if (it != m_scaffoldObjectIDList.end()) {
        do {
            ObjectID id = *it;
            Object *object = TheGameLogic->findObjectByID(id);
            if (object) {
                BridgeScaffoldBehavior::getBridgeScaffoldBehaviorInterfaceFromObject(object)->reverseMotion();
            }
            ++it;
        } while (it != m_scaffoldObjectIDList.end());
    }
    m_scaffoldObjectIDList.clear();
    m_scaffoldPresent = false;
    Object *object = getObject();
    if (object->getBodyModule()->getDamageState() != BODY_RUBBLE) {
        Bridge *bridge = TheTerrainLogic->findBridgeAt(object->getPosition());
        if (bridge)
            TheAI->pathfinder()->SetBridgeStateRepaired(bridge->getLayer(), true);
    }
}

// FUNCTION: BFME2 0x004573D4 size=75 name=?isScaffoldInMotion@BridgeBehavior@@UAE_NXZ evidence=N:ledger
bool BridgeBehavior::isScaffoldInMotion()
{
    ObjectIDListIterator it = m_scaffoldObjectIDList.begin();
    if (it != m_scaffoldObjectIDList.end()) {
        do {
            Object *object = TheGameLogic->findObjectByID(*it);
            if (object) {
                BridgeScaffoldBehaviorInterface *scaffold =
                    BridgeScaffoldBehavior::getBridgeScaffoldBehaviorInterfaceFromObject(object);
                if (scaffold && scaffold->getCurrentMotion() != STM_STILL) return true;
            }
            ++it;
        } while (it != m_scaffoldObjectIDList.end());
    }
    return false;
}

// FUNCTION: BFME2 0x00457472 size=196 name=??0BridgeBehavior@@QAE@PAVThing@@PBVModuleData@@@Z evidence=N:ledger
BridgeBehavior::BridgeBehavior(Thing *thing, const ModuleData *data) : UpdateModule(thing, data)
{
    m_scaffoldObjectIDList.clear();
    m_scaffoldPresent = false;
    memset(m_towerID, 0, sizeof(m_towerID));
    m_fxResolved = false;
    for (int state = 0; state < 4; ++state)
        for (int effect = 0; effect < 3; ++effect) {
            m_damageToOCL[state][effect] = 0;
            m_damageToFX[state][effect] = 0;
            m_repairToOCL[state][effect] = 0;
            m_repairToFX[state][effect] = 0;
        }
    m_deathFrame = 0;
}

// FUNCTION: BFME2 0x00457577 size=448 name=?handleObjectsOnBridgeOnDie@BridgeBehavior@@IAEXXZ evidence=N:ledger
void BridgeBehavior::handleObjectsOnBridgeOnDie()
{
	const Object *bridge = getObject();
	const Coord3D *bridgePos = bridge->getPosition();

	Bridge *terrainBridge = TheTerrainLogic->findBridgeAt(getObject()->getPosition());
	if (terrainBridge)
	{
		PathfindLayerEnum bridgeLayer = terrainBridge->getLayer();

		BridgeInfo bridgeInfo;
		bridgeInfo = terrainBridge->m_bridgeInfo;

		// a polygon area from the bridge extents
		Coord3D bridgePolygon[4];
		bridgePolygon[0] = bridgeInfo.fromLeft;
		bridgePolygon[1] = bridgeInfo.fromRight;
		bridgePolygon[2] = bridgeInfo.toRight;
		bridgePolygon[3] = bridgeInfo.toLeft;

		// the lowest Z of the area tells which objects are "on top" of the bridge
		Real lowBridgeZ = bridgePolygon[0].z;
		for (Int i = 0; i < 4; ++i)
			if (bridgePolygon[i].z < lowBridgeZ)
				lowBridgeZ = bridgePolygon[i].z;

		// the radius to scan: from the bridge center to the edge
		Coord2D v;
		v.x = bridgeInfo.toLeft.x - bridgePos->x;
		v.y = bridgeInfo.toLeft.y - bridgePos->y;
		Real radius = v.length();

		ObjectIterator iter = ThePartitionManager->rva006255D0(bridgePos, radius, 0, 0);
		Object *other;
		while ((other = iter.next()) != NULL)
		{
			// bridges and their towers are ignored
			if (other->getTemplate()->isKindOf((KindOfType)22) || other->getTemplate()->isKindOf((KindOfType)24))
				continue;

			// so are airborne objects
			if (other->isAboveTerrain())
				continue;

			// and objects that were not actually on the bridge
			if (other->getPosition()->z < lowBridgeZ)
				continue;

			if (PointInsideArea2D(other->getPosition(), bridgePolygon, 4) == FALSE)
				continue;

			if (bridgeLayer != other->rva0028B511())
				continue;

			if (other->rva0028B511() == bridgeLayer)
				other->setLayer((PathfindLayerEnum)1);

			other->kill(DAMAGE_UNRESISTABLE, (DeathType)0);
		}
	}
}

// FUNCTION: BFME2 0x00457737 size=1851 name=?createScaffolding@BridgeBehavior@@UAEXXZ evidence=N:ledger

// FUNCTION: BFME2 0x00457E72 size=357 name=?xfer@BridgeBehavior@@MAEXPAVXfer@@@Z evidence=N:ledger
void BridgeBehavior::xfer(Xfer *xfer)
{
	UpdateModule::xfer(xfer);

	if (xfer->IsLightCRC())
		return;

	Object *us = getObject();

	xfer->Version1();

	// set us as the bridge object in the bridge info
	if (xfer->IsLoading())
	{
		Bridge *bridge = TheTerrainLogic->findBridgeAt(us->getPosition());
		bridge->setBridgeObjectID(us->getID());
	}

	for (Int i = 0; i < BRIDGE_MAX_TOWERS; ++i)
		XferObjectID(xfer, &m_towerID[i]);

	// set the tower object ids in the bridge info
	if (xfer->IsLoading())
	{
		Bridge *bridge = TheTerrainLogic->findBridgeAt(us->getPosition());
		for (Int i = 0; i < BRIDGE_MAX_TOWERS; ++i)
			bridge->setTowerObjectID(m_towerID[i], i);
	}

	*xfer == m_scaffoldPresent;

	UnsignedShort scaffoldObjectCount = 0;
	scaffoldObjectCount = m_scaffoldObjectIDList.size();
	*xfer == scaffoldObjectCount;
	ObjectID scaffoldObjectID;
	if (xfer->IsStoring())
	{
		for (ObjectIDListIterator it = m_scaffoldObjectIDList.begin(); it != m_scaffoldObjectIDList.end(); ++it)
		{
			scaffoldObjectID = *it;
			XferObjectID(xfer, &scaffoldObjectID);
		}
	}
	else
	{
		for (UnsignedInt i = 0; i < scaffoldObjectCount; ++i)
		{
			XferObjectID(xfer, &scaffoldObjectID);
			m_scaffoldObjectIDList.push_back(scaffoldObjectID);
		}
	}

	*xfer == m_deathFrame;

	*xfer == m_fxResolved;
}

