// FUNCTION: BFME2 0x004580A9 size=170 name=?parseFX@BridgeBehaviorModuleData@@SAXPAVINI@@PAX1PBX@Z evidence=N:ledger
void BridgeBehaviorModuleData::parseFX(INI *ini, void *instance, void *store, const void *userData)
{
	const char *token;

	BridgeFXInfo item;
	item.fx = NULL;

	BridgeFXList *bridgeFXList = (BridgeFXList *)store;

	token = ini->getNextToken(ini->getSepsColon());
	if (BridgeBehaviorCRT::_strcmpi(token, "FX") != 0)
		throw INIException(3, "Expected 'FX' token, found '%s'\n", token);

	FXList *fx;
	ini->parseFXList(ini, instance, &fx, NULL);
	item.fx = fx;

	parseTimeAndLocationInfo(ini, instance, &item.timeAndLocationInfo);

	bridgeFXList->push_back(item);
}

// FUNCTION: BFME2 0x00458153 size=170 name=?parseOCL@BridgeBehaviorModuleData@@SAXPAVINI@@PAX1PBX@Z evidence=N:ledger
void BridgeBehaviorModuleData::parseOCL(INI *ini, void *instance, void *store, const void *userData)
{
	const char *token;

	BridgeOCLInfo item;
	item.ocl = NULL;

	BridgeOCLList *bridgeOCLList = (BridgeOCLList *)store;

	token = ini->getNextToken(ini->getSepsColon());
	if (BridgeBehaviorCRT::_strcmpi(token, "OCL") != 0)
		throw INIException(3, "Expected 'OCL' token, found '%s'\n", token);

	ObjectCreationList *ocl;
	ini->parseObjectCreationList(ini, instance, &ocl, NULL);
	item.ocl = ocl;

	parseTimeAndLocationInfo(ini, instance, &item.timeAndLocationInfo);

	bridgeOCLList->push_back(item);
}

// FUNCTION: BFME2 0x004581FD size=79 name=?onDie@BridgeBehavior@@UAEXPBVDamageInfo@@@Z evidence=N:ledger
void BridgeBehavior::onDie(const DamageInfo *)
{
    for (int towerIndex = 0; towerIndex < BRIDGE_MAX_TOWERS; ++towerIndex) {
        Object *tower = TheGameLogic->findObjectByID(getTowerID((BridgeTowerType)towerIndex));
        if (tower) tower->kill((DamageType)8, (DeathType)0);
    }
    handleObjectsOnBridgeOnDie();
    m_deathFrame = TheGameLogic->getFrame();
}

